head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[xml > M > appendChild]<br/>대상 노드의 하위에 자식 노드를 추가합니다.",
    "validation" : [
        "descNode(필수) 파라미터로 자식 노드를 추가할 부모 노드를 설정할 수 있어야 합니다.",
        "childNode(필수) 파라미터로 추가할 자식 노드를 설정할 수 있어야 합니다.",
        "추가된 노드를 반환해야 합니다.",
        "descNode 와 childNode 의 ownerDocument 가 다른 경우 importNode 를 통해 자동으로 노드를 가져온 후 추가해야 합니다.",
        "서로 다른 XML Document 에 속한 노드를 추가할 때 importNode 의 deep 옵션이 true 로 설정되어 하위 노드까지 모두 복사되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_appendChild_same_onclick = function () {
    // 동일 Document 내 appendChild
    var doc = WebSquare.xml.parse("<bookstore><book><title>Harry Potter</title></book></bookstore>");
    var bookNode = WebSquare.xml.findNode(doc, "bookstore/book");

    // 같은 Document 에서 새 노드 생성
    var priceNode = doc.createElement("price");
    priceNode.textContent = "29.99";

    var result = WebSquare.xml.appendChild(bookNode, priceNode);

    var xmlStr = WebSquare.xml.serialize(doc);
    wf_body_bottom.getObj("scwin").setReturnValue("동일 Document appendChild");
    wf_body_bottom.getObj("scwin").setReturnValue("결과 XML : " + xmlStr);
    wf_body_bottom.getObj("scwin").setReturnValue("반환 노드 : " + (result ? result.nodeName : "null"));
    wf_body_bottom.getObj("scwin").setReturnValue("price 포함 확인 : " + (xmlStr.indexOf("price") >= 0 ? "PASS" : "FAIL"));
}



scwin.btn_appendChild_diff_onclick = function () {
    // 서로 다른 Document 의 노드를 추가 (importNode 자동 처리)
    var doc1 = WebSquare.xml.parse("<bookstore><book><title>Harry Potter</title></book></bookstore>");
    var doc2 = WebSquare.xml.parse("<author>J. K. Rowling</author>");

    var bookNode = WebSquare.xml.findNode(doc1, "bookstore/book");
    var authorNode = WebSquare.xml.findNode(doc2, "author");

    var result = WebSquare.xml.appendChild(bookNode, authorNode);

    var xmlStr = WebSquare.xml.serialize(doc1);
    wf_body_bottom.getObj("scwin").setReturnValue("다른 Document appendChild (importNode)");
    wf_body_bottom.getObj("scwin").setReturnValue("결과 XML : " + xmlStr);
    wf_body_bottom.getObj("scwin").setReturnValue("반환 노드 : " + (result ? result.nodeName : "null"));
    wf_body_bottom.getObj("scwin").setReturnValue("author 포함 확인 : " + (xmlStr.indexOf("author") >= 0 ? "PASS" : "FAIL"));
    wf_body_bottom.getObj("scwin").setReturnValue("텍스트 포함 확인 : " + (xmlStr.indexOf("J. K. Rowling") >= 0 ? "PASS" : "FAIL"));
}



scwin.btn_appendChild_deep_onclick = function () {
    // 하위 노드가 있는 경우 deep 복사 확인
    var doc1 = WebSquare.xml.parse("<root><parent></parent></root>");
    var doc2 = WebSquare.xml.parse("<child><grandchild>deep copy test</grandchild><grandchild2>second</grandchild2></child>");

    var parentNode = WebSquare.xml.findNode(doc1, "root/parent");
    var childNode = WebSquare.xml.findNode(doc2, "child");

    WebSquare.xml.appendChild(parentNode, childNode);

    var xmlStr = WebSquare.xml.serialize(doc1);
    wf_body_bottom.getObj("scwin").setReturnValue("deep 복사 확인 (하위 노드 포함)");
    wf_body_bottom.getObj("scwin").setReturnValue("결과 XML : " + xmlStr);
    wf_body_bottom.getObj("scwin").setReturnValue("grandchild 포함 : " + (xmlStr.indexOf("grandchild") >= 0 ? "PASS" : "FAIL"));
    wf_body_bottom.getObj("scwin").setReturnValue("grandchild2 포함 : " + (xmlStr.indexOf("grandchild2") >= 0 ? "PASS" : "FAIL"));
    wf_body_bottom.getObj("scwin").setReturnValue("텍스트 포함 : " + (xmlStr.indexOf("deep copy test") >= 0 ? "PASS" : "FAIL"));
}
